options.css:
* { box-sizing: border-box; margin: 0; padding: 0; }
body { background: transparent; font-family: Georgia, serif; color: #cde; }

.wrap {
  background: #0a1628;
  border-radius: 10px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* ── Location buttons ── */
.loc-btns { display: flex; gap: 8px; flex-wrap: wrap; }
.loc-btn {
  background: rgba(255,255,255,0.08);
  color: #7eb8ff;
  border: 1px solid rgba(30,144,255,0.3);
  border-radius: 20px;
  padding: 5px 14px;
  font-size: 12px;
  cursor: pointer;
  transition: all 0.2s;
  font-family: Georgia, serif;
}
.loc-btn.active { background: #1e90ff; color: #fff; border-color: #1e90ff; }
.loc-btn:hover  { background: rgba(30,144,255,0.2); }

/* ── Date row ── */
.date-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.nav-btn {
  background: rgba(255,255,255,0.07);
  color: #7eb8ff;
  border: 1px solid rgba(30,144,255,0.3);
  border-radius: 8px;
  padding: 4px 12px;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s;
  font-family: Georgia, serif;
}
.nav-btn:hover  { background: rgba(30,144,255,0.2); border-color: #1e90ff; color: #fff; }
.today-btn      { font-size: 11px; padding: 4px 10px; color: #48dbfb; border-color: rgba(72,219,251,0.4); }
.today-btn:hover{ background: rgba(72,219,251,0.15); border-color: #48dbfb; }
#datePicker {
  background: #0d1f3c;
  border: 1px solid rgba(30,144,255,0.4);
  border-radius: 8px;
  color: #7eb8ff;
  font-size: 13px;
  padding: 4px 10px;
  cursor: pointer;
  outline: none;
  font-family: Georgia, serif;
}
#datePicker::-webkit-calendar-picker-indicator {
  filter: invert(0.6) sepia(1) saturate(5) hue-rotate(175deg);
  cursor: pointer;
}
.date-display { font-size: 11px; color: #3d5a7a; margin-left: 4px; }

/* ── Weather strip ── */
.wx-strip {
  background: rgba(30,144,255,0.06);
  border: 1px solid rgba(30,144,255,0.12);
  border-radius: 8px;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.wx-strip-main {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}
.wx-big-temp {
  font-size: 28px;
  font-weight: bold;
  color: #fff;
  line-height: 1;
}
.wx-feels { font-size: 12px; color: #5a7fa0; }
.wx-desc  { font-size: 13px; color: #b0c8e8; }
.wx-strip-stats {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}
.wx-stat      { font-size: 11px; color: #7eb8ff; white-space: nowrap; }
.trend-stat   { font-size: 14px; font-weight: bold; }

/* ── Barometer bar ── */
.baro-row {
  display: flex;
  align-items: center;
  gap: 6px;
}
.baro-label-left, .baro-label-right {
  font-size: 9px;
  color: #3d5a7a;
  white-space: nowrap;
}
.baro-track {
  flex: 1;
  position: relative;
  height: 6px;
  background: rgba(255,255,255,0.07);
  border-radius: 3px;
  overflow: visible;
}
.baro-fill {
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, #ff4757 0%, #ffd32a 35%, #2ed573 55%, #1e90ff 100%);
  transition: width 0.5s;
}
.baro-marker {
  position: absolute;
  top: -4px;
  width: 3px;
  height: 14px;
  background: #fff;
  border-radius: 2px;
  transform: translateX(-50%);
  transition: left 0.5s;
  box-shadow: 0 0 5px rgba(255,255,255,0.8);
}
.baro-hint {
  font-size: 10px;
  color: #ffd32a;
  white-space: nowrap;
  min-width: 140px;
}

/* ── Score bar ── */
.score-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  min-height: 24px;
  padding: 2px 0;
  border-top: 1px solid rgba(255,255,255,0.05);
}
.score-pill {
  border-radius: 20px;
  padding: 3px 12px;
  font-size: 12px;
  font-weight: bold;
}
.score-stat { font-size: 11px; color: #5a7fa0; }

/* ── Chart ── */
.chart-wrap { position: relative; width: 100%; height: 220px; }

/* ── Fishing impact bar ── */
.impact-bar {
  font-size: 11px;
  color: #b0c8e8;
  line-height: 1.6;
  padding: 4px 0;
  border-top: 1px solid rgba(255,255,255,0.05);
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

/* ── Legend ── */
.legend {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  font-size: 11px;
  color: #5a7fa0;
  align-items: center;
  border-top: 1px solid rgba(255,255,255,0.05);
  padding-top: 6px;
}
.ldot {
  width: 12px;
  height: 10px;
  border-radius: 2px;
  display: inline-block;
  margin-right: 3px;
  vertical-align: middle;
}
.msg { color: #5a7fa0; font-size: 12px; }
.err { color: #ff6b6b; font-size: 12px; }

